import fs from 'node:fs/promises';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
const out='review-evidence/no-brow-editable-bundle';await fs.mkdir(out+'/assets',{recursive:true});
const b=await chromium.launch({executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});const p=await b.newPage({viewport:{width:1600,height:900}});await p.goto('http://127.0.0.1:8140/review-evidence/selected-gesture-review/');await p.waitForFunction(()=>window.selectedReview?.ready);
const tree=await p.evaluate(()=>{const svg=document.querySelector('#after svg').cloneNode(true);svg.removeAttribute('data-comparison');svg.setAttribute('id','ranca-cana');svg.setAttribute('role','img');svg.setAttribute('aria-label','Ranca and Cana without eyebrows');for(const c of svg.querySelectorAll('[data-character]')){const key=c.dataset.character;c.id=key+'-placement';c.querySelector('image').id=key+'-body';c.querySelector('[data-face-map]').id=key+'-face-placement';const f=c.querySelector('[data-preserved-face]');f.id=key+'-face';f.lastElementChild.id=key+'-mouth';[...f.children].filter(n=>n.tagName.toLowerCase()==='g').forEach((g,i)=>{const side=i?'right':'left';g.id=key+'-'+side+'-eye-group';g.querySelector('[data-line-eye]').id=key+'-'+side+'-eye';const lashes=g.querySelector('[data-lashes]');if(lashes)lashes.id=key+'-'+side+'-lashes';});for(const g of c.querySelectorAll('[data-limb]')){g.id=key+'-'+g.dataset.limb+'-hand-group';g.querySelector('[data-arm]').id=key+'-'+g.querySelector('[data-arm]').dataset.arm+'-arm';g.querySelector('[data-palm]').id=key+'-'+g.querySelector('[data-palm]').dataset.palm+'-palm';}}
for(const t of svg.querySelectorAll('text')){t.setAttribute('font-family','system-ui, sans-serif');t.setAttribute('font-size','32');t.setAttribute('fill','#f1f7ee');t.setAttribute('text-anchor','middle');}
const serialize=n=>({tag:n.tagName,attributes:Object.fromEntries([...n.attributes].map(a=>[a.name,a.value])),children:[...n.childNodes].filter(c=>c.nodeType===1||c.nodeType===3&&c.textContent.trim()).map(c=>c.nodeType===1?serialize(c):c.textContent)});return serialize(svg);});
await fs.writeFile(out+'/editable-layers.json',JSON.stringify(tree,null,2)+'\n');for(const key of ['ranca','cana'])await fs.copyFile('review-evidence/selected-gesture-review/'+key+'-body.webp',out+'/assets/'+key+'-body.webp');await fs.copyFile('review-evidence/selected-gesture-output/comparison-check.json',out+'/no-brow-check.json');await b.close();console.log('Exported named SVG layer tree and unchanged body images.');
